.lotusImagesOff .wpToolbarCommonImages{display:none}

.wpToolbarCommon .wpToolbarAltText,
.wpToolbarCommon .wpToolbarImagesOff {
    display: none;
}
.lotusImagesOff .wpToolbarCommon img,
.wpthemeImagesOff .wpToolbarCommon img,
.lotusImagesOff.wpToolbarCommon img,
.wpthemeImagesOff.wpToolbarCommon img {
