/* video intro */

.post .content_video {
    width: 100%;
    margin: 25px 0 0 0;
}

.video_wrap {
    position: relative;
    margin-bottom: 20px;
}

.video_wrap .video_intro {
    position: absolute;
    width: 100%;
    height: auto;
    top: 10%;
    bottom: 0;
    text-align: center;
    color: #fff;
    padding: 0 0.5rem;
    -webkit-transition: all 0.3s ease-in;
    -moz-transition: all 0.3s ease-in;
    -ms-transition: all 0.3s ease-in;
    transition: all 0.3s ease-in;
}

.video_wrap .video_intro.toggle {
    -webkit-transform: scale(2);
    -moz-transform: scale(2);
    -ms-transform: scale(2);
    transform: scale(2);
    opacity: 0;
    visibility: hidden;
}

.video_wrap #video_pic {
    -webkit-transition: all 0.3s ease-in;
    -moz-transition: all 0.3s ease-in;
    -ms-transition: all 0.3s ease-in;
    transition: all 0.3s ease-in;
}

.video_wrap #video_pic.toggle {
    opacity: 0;
    visibility: hidden;
}

.video_wrap #index_video {
    position: absolute;
    top: 0;
    left: 0;
    z-index: -10;
    -webkit-transition: all 0.3s ease-in;
    -moz-transition: all 0.3s ease-in;
    -ms-transition: all 0.3s ease-in;
    transition: all 0.3s ease-in;
}

.video_wrap #index_video.focus {
    z-index: 10;
}

.video_wrap #close_video {
    position: absolute;
    right: 20px;
    top: 20px;
    z-index: 100;
    visibility: hidden;
    opacity: 0;
    z-index: -10;
    font-weight: bold;
    font-size: 14px;
    font-size: 0.875em;
    -webkit-transition: all 0.3s ease-in;
    -moz-transition: all 0.3s ease-in;
    -ms-transition: all 0.3s ease-in;
    transition: all 0.3s ease-in;
}

.video_wrap #close_video.toggle {
    visibility: visible;
    z-index: 10;
    opacity: 1;
}

@media only screen and (min-width:65em) {
    .video_wrap .video_intro {
        position: absolute;
        top: 50%;
        left: 50%;
        margin-left: -320px;
        margin-top: -100px;
        width: 640px;
        height: 200px;
        text-align: center;
        color: #fff;
    }
}

.video_wrap .video_intro p {
    font-size: 18px;
