/* Prevent video jerky resize on load, reset defaults */

video {
    width: 100%;
    height: 100%;
    display: inline-block;
    vertical-align: baseline;
}

#video_wrap {
    height: 300px;
    width: 100%;
    position: relative;
}

#video_wrap a#trigger_video {
    position: absolute;
    background: #099ee8 url("/wps/contenthandler/!ut/p/digest!YuhzijIF0sKEVnS8UwWCRg/war/tadawul.portal.theme.static.v2/themes/Tadawul/images/ico/ico-play-video.png") no-repeat 39px 36px;
    width: 90px;
    height: 90px;
    top: 50%;
    left: 50%;
    margin-left: -45px;
    margin-top: -45px;
    border-radius: 50em;
    -webkit-transition: all 0.25s ease-in;
    -moz-transition: all 0.25s ease-in;
    -ms-transition: all 0.25s ease-in;
    transition: all 0.25s ease-in;
    opacity: 1;
    visibility: visible;
}

#video_wrap a#trigger_video.toggle {
    opacity: 0;
    visibility: hidden;
}

#video_wrap a#trigger_video:hover {
    background-color: #64b938;
}

#video_wrap a#close_media {
    position: absolute;
    bottom: 0;
    right: 0;
    padding: 5px 10px;
    font-size: 12px;
    font-size: 0.75em;
    background: #099ee8;
    color: #fff;
    opacity: 0;
    visibility: hidden;
    -webkit-transform: translateY(0);
    -moz-transform: translateY(0);
    -ms-transform: translateY(0);
    transform: translateY(0);
    -webkit-transition: all 0.25s ease-in;
    -moz-transition: all 0.25s ease-in;
    -ms-transition: all 0.25s ease-in;
    transition: all 0.25s ease-in;
}

#video_wrap a#close_media.show {
    opacity: 1;
    visibility: visible;
    -webkit-transform: translateY(35px);
    -moz-transform: translateY(35px);
    -ms-transform: translateY(35px);
    transform: translateY(35px);
}

#video_wrap a#close_media:hover {
    text-decoration: none;
    background: #64b938;
}

#video_wrap {
    position: relative;
    padding-bottom: 46.25%;
    /* 16:9 */
    padding-top: 25px;
    height: 0;
}

@media only screen and (min-width:49.5em) {
    #video_wrap {
        padding-bottom: 46.25%;
        /* 16:9 */
    }
}

#video_wrap iframe {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 0;
    opacity: 0;
    -webkit-transition: all 0.3s ease-in;
    -moz-transition: all 0.3s ease-in;
    -ms-transition: all 0.3s ease-in;
    transition: all 0.3s ease-in;
}

#video_wrap.toggle iframe {
    height: 100%;
    opacity: 1;
}


