.error404 {
    position: relative;
    margin: 22px 0 40px 0;
    padding: 0 0 0 230px;
}

.error404:before {
    content: "404";
    display: block;
    width: 164px;
    height: 164px;
    font-size: 60px;
    line-height: 164px;
    color: #fff;
