    font-size: 60px;
    line-height: 60px;
    font-weight: bold;
    color: #333;
    padding: 13px 0;
    letter-spacing: -1px;
}

.error404 .subtitle {
    font-size: 24px;
    line-height: 34px;
    font-weight: bold;
    color: #0045E3;
    text-transform: uppercase;
