/**
 * SpinnerDiv
 * @param {[type]} $selector jQuery selector for conatiner]
 * @param {[type]} options   timeout and Markup options
 */
var SpinnerDiv = function($selector, options){

    var self = this;
    
    var timer = false;
    var spinner = false;
    var option = (options===undefined) ? {} : options;

    var setup = {
        'timeout': 60,
        'markup': '<div class="loading"></div>',
        'class': '.loading',
        'hideElement': false
    }
    $.extend(setup, options);

    /**
     * Show spinner
     * @return {[type]} [description]
     */
    var show = function(callback) {

        callback = (typeof callback === "function") ? callback : function(){};


        if(setup.hideElement)
        {
          setup.hideElement.hide();
        }

        $selector.append(setup.markup);

        callback();

        // Timeout
        if(setup.timeout>0)
        {
            timer = setTimeout(function(){
                $selector.find(setup.spinnerClass).remove();
            }, setup.timeout * 1000);
        }

        return {
            show: show, 
            hide: hide 
        }
    }

    /**
     * Hide spiner
     * @return {[type]} [description]
     */
    var hide =  function(callback) {

        callback = (typeof callback === "function") ? callback : function(){};

        if(setup.hideElement)
        {
          setup.hideElement.show();
        }

        $selector.find(setup.class).remove();

        callback();

        // Timeout
        if(setup.timeout>0)
        {
            clearTimeout(timer);
        }

        return {
            show: show, 
            hide: hide 
        }
    }   

    return {
        show: show, 
        hide: hide 
    };
};
