(function(twitter) {
    
    let twitterHandler = {
        timelines : "",
        tags : {
            author      : ".TweetAuthor-screenName.Identity-screenName",
            authorLink  : ".TweetAuthor-link",
            date        : ".dt-updated",
            DOM         : ".timeline-TweetList-tweet",
            link        : ".timeline-Tweet",
            linkAttr    : "data-click-to-open-target",
            linkQuery   : "?ref_src=twsrc^tfw|twcamp^embeddedtimeline",
            play        : ".NaturalImage-ctaOverlay.PlayButton",
            thumb       : ".NaturalImage-image",
            tweet       : ".timeline-Tweet-text"
        },
        
        onRender : false,
        
        start : function(){
            console.log("twitterHandler.start")
            this.tweets = $("#tweets");
            window.twttr = (function(d, s, id) {
                var js, fjs = d.getElementsByTagName(s)[0],
                    t = window.twttr || {};
                if (d.getElementById(id)) return;
                js = d.createElement(s);
                js.id = id;
                js.src = "https://platform.twitter.com/widgets.js";
                fjs.parentNode.insertBefore(js, fjs);
                
                t._e = [];
                t.ready = function(f) {
                    t._e.push(f);
                };
                
                return t;
            }(document, "script", "twitter-wjs"));
            
            setTimeout(function(){
                twttr.ready(function (twttr) {
                    twttr.events.bind(
                        'rendered',
                        function (event) {
    
                            if (!twitterHandler.onRender){
                                twitterHandler.onRender = true;
                                console.log("twitter renderer");
    
                                twitterHandler.timelines = $.parseHTML($("iframe").contents().find(".timeline-TweetList").html().replace("\n",""));
                                document["timelines"] = $("<div id='timelines'></div>");
                                twitterHandler.timelines = document["timelines"].append(twitterHandler.timelines);
                                twitterHandler.populateTweets();
                                //$("#original-tweets").remove();
                            }
                        }
                    );
                });
            }, 300)
        },
        
        populateTweets : function(){
            let i,
            li = $("<li data-tweet=''></li>"),
            div = $("<div></div>"),
            a = $("<a href='' target='_blank'></a>"),
            span = $("<span class='date'></span>"),
            spanP = $("<span class='play'></span>"),
            p = $("<p></p>"),
            img = $("<figure><img/></figure>"),
            liTweetContainer,
            thumbnail,
            divCaption,
            author,
            pTweet,
            spanDate,
            spanPlay;
            
            this.timelines.find(this.tags.DOM).each(function(){
                let _this = $(this),
                    authorContainer;
                
                authorContainer = _this.find(twitterHandler.tags.authorLink);
    
                author = a.clone();
                spanDate = span.clone();
                pTweet = p.clone();
                divCaption = div.clone();
                liTweetContainer = li.clone();
    
                pTweet.html(_this.find(twitterHandler.tags.tweet).html());
                
                pTweet.find("a").each(function(){
                    $(this).attr("target", "_blank")
                })
    
                author
                    .attr("href", authorContainer.attr("href"))
                    .html(_this.find(twitterHandler.tags.author).html());
                
                spanDate.html(_this.find(twitterHandler.tags.date).html());
    
                divCaption
                    .append(
                        author,
                        pTweet,
                        spanDate
                    )
    
                liTweetContainer
                    .attr("data-tweet", _this.find(twitterHandler.tags.link).attr(twitterHandler.tags.linkAttr) + twitterHandler.tags.linkQuery)
                    .append(divCaption);
                
                if (_this.find(twitterHandler.tags.thumb).length){
                    thumbnail = img.clone();
                    thumbnail.find("img").attr("src", _this.find(twitterHandler.tags.thumb).attr("src"));
                    liTweetContainer.prepend(thumbnail);
    
                    if (_this.find(twitterHandler.tags.play).length){
                        spanPlay = spanP.clone();
                        thumbnail.append(spanPlay)
                    }
                }
                twitterHandler.tweets.append(liTweetContainer)
            })
            
            this.events();
            
        },
        
        events : function(){
            twitterHandler.tweets.on("click", "li", function(e){
                let _this = $(this);
                if (e.target.tagName !== "A" && $(e.target).closest("a").length === 0){
                    window.open(_this.attr("data-tweet"), "_blank")
                }
            })
        }
    }
    
    
    
    $(document).ready(function(){
        /** do not activate: is already present in scripts.js and works better and once
        
        if ($("#twitter-container").length){
            twitterHandler.start();
        }**/
        
    });
    
    
    
})('#twitter-container');
