try{function renderTASINavChart(){
	var chartSeriesData = [];
	var yAxisMinMaxCal = [];
	$.ajax({
		url:'/Charts/ChartGenerator?chart-type=SQL_MI_MSPV&chart-parameter=tasi&methodType=parsingMethod',
		dataType: 'json',
		type:'GET',
		success:function(TASITrade){
			if(TASITrade.length > 0){
				for(var i=0;i<TASITrade.length;i++){
					try{
						chartSeriesData.push([moment(TASITrade[i].dateTime).valueOf(),TASITrade[i].indexPrice]);
						yAxisMinMaxCal.push(TASITrade[i].indexPrice);
					}catch(error){
					}
				}
			}
			var min = Math.min.apply(Math,yAxisMinMaxCal);
			var max = Math.max.apply(Math,yAxisMinMaxCal);
			var chartHeight = 270;
			if(userCurrentLocale == 'en')
				chartHeight = 270;
		    $('#chart_nav').highcharts('StockChart', {
		        chart : {
		        	 type: 'area',
		             margin: [40, 0, 20, 0],
		             height:chartHeight,
		             backgroundColor: '#001F33'
		        },
		        rangeSelector: {
		           enabled: false
		        },
		        series: [{
		        	name: 'TASI',
		            data: chartSeriesData,
		            line: 'line',
		            lineColor: '#40C1AC',
		            shadow: false,
		            lineWidth: 1,
		            fillOpacity: 1,
		            color: '#40C1AC',
		            fillColor:'#5BCAB8'
		           
		        }],
		        xAxis: {
		        	enabled:false,
		            gridLineColor: '#192d34',
		            gridLineWidth: 0,
		            lineColor: '#192d34',
		            tickColor: '#192d34'
		        },
		        yAxis: {
		        	min:min,
		        	max:max,
		        	enabled:false,
		            showFirstLabel: false,
		            gridLineColor: '#192d34',
		            labels: {enabled:false},
		            gridLineDashStyle: 'ShortDot',
		            lineColor: '#192d34',
		            tickColor: '#192d34',
		            tickWidth: 0
		        },
		        tooltip: {
		            crosshairs: false,
		            enabled: true,
		            backgroundColor: '#001F33',
		            borderWidth: 0,
		            shadow:false,
		            useHTML:true,
		            style: {
		                color: '#FFFFFF',
		                padding: '10px'
		            }
		        },
		        exporting: {
		            enabled: false
		        },
		        credits: {
		              enabled: false
		        },
		        navigator : {
		            enabled : false
		            },
		        scrollbar : {
		            enabled: false
		        }
		    });
		    $('#chart_nav').highcharts().reflow();
		},
		error:function(e){
		}
	});
};
function setTASIChartValues(){
	if(marketInformation != undefined){
		$("#tasiNavVal").text(marketInformation.tasiValue);
		$("#tasiNetChangeVal").text(marketInformation.tasiNetChange);
		$("#tasiPercChangeVal").text("("+marketInformation.tasiPercentageChange+"%)");
		$("#tasiIndicator").removeClass();
		if (marketInformation.tasiNetChange < 0) {
			$("#tasiIndicator").addClass("red");
		}else if (marketInformation.tasiNetChange > 0) {
			$("#tasiIndicator").addClass("green");
		}else{
			$("#tasiIndicator").addClass("white");
		}
	}
 };
 function loadTASINavValuesAndChart(){
	 
	 setTASIChartValues();
 };
