/**
 * Synchronize zooming through the setExtremes event handler.
 */
function syncExtremes(e) {
	//alert(syncExtremes);
	var thisChart = this.chart;

	if (e.trigger !== 'syncExtremes') { // Prevent feedback loop
		Highcharts.each(Highcharts.charts, function (chart) {
			//chart.redraw();
			if (chart !== thisChart) {
				if (chart.xAxis[0].setExtremes) { // It is null while updating
					chart.xAxis[0].setExtremes(
						e.min,
						e.max,
						undefined,
						false,
						{ trigger: 'syncExtremes' }
					);
				}
			}
		});
	}
}

function getSelectedRange(defaultrangeSelector, endTime) {
	let start;
	const end = endTime;

	switch (defaultrangeSelector) {
		case 0: // 1 day
			start = endTime - (24 * 3600 * 1000);
			break;
		case 1: // 5 days
			start = endTime - (6 * 24 * 3600 * 1000);
			break;
		case 2: // 1 month (approx 30 days)
			start = endTime - (30 * 24 * 3600 * 1000);
			break;
		case 3: // 3 months (approx 90 days)
			start = endTime - (90 * 24 * 3600 * 1000);
			break;
		case 4: // 1 year (365 days)
			start = endTime - (365 * 24 * 3600 * 1000);
			break;
		case 5: // 3 years
			start = endTime - (3 * 365 * 24 * 3600 * 1000);
			break;
		case 6: // All
			start = 0;
			break;
		default:
			start = 0;
	}

	return { start, end };
}

function canAllowCustomTickPositioner(defaultrangeSelector) {
	var day = 24 * 3600 * 1000;
	var duration = 1 * day;
	switch (defaultrangeSelector) {
		case 1:
		case "1":
			duration = 6 * day;
			break;
		case 2:
		case "2":
			duration = 30 * day;
			break;
		case 3:
		case "3":
			duration = 90 * day;
			break;
		case 4:
		case "4":
			duration = 365 * day;
			break;
		default:
			duration = 30 * day;
	}
	return (max-min) > duration
}

